using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF 9 removed HasIndex for Cosmos (indexes are
            // managed server-side via indexing policy, not EF).
            // REMOVED: entity.HasIndex(b => b.Name);

            // Breaking change 2: EF 9 renamed the discriminator property from
            // "Discriminator" to "$type". Existing documents still store
            // "Discriminator", so we pin the old name for compatibility.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 3: EF 9 changed the id format from
            // "EntityName|KeyValue" to just "KeyValue". Existing documents use
            // the old format, so we opt back in to the legacy id format.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyCosmosIdGenerator>();
        });
    }
}

/// <summary>
/// Reproduces the EF 8 id format "EntityType|Key" so existing documents are
/// still reachable.
/// </summary>
class LegacyCosmosIdGenerator : Microsoft.EntityFrameworkCore.ValueGeneration.ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(Microsoft.EntityFrameworkCore.ChangeTracking.EntityEntry entry)
    {
        var key = entry.Property("Id").CurrentValue?.ToString();
        return $"Blog|{key}";
    }
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

